template <typename T> void twice(T * out, int64_t n) {
    int64_t i = __nfcxx_ctaid_x() * __nfcxx_ntid_x() + __nfcxx_tid_x();
    if (i < n) out[i] = (T) (2 * i);
}
extern "C" void __nfcxx_k_twice_int(int * out, int64_t n) { twice<int>(out, n); }
